/**
 * The artwork set (static/artwork, generated by scripts/brand/build_artwork.py): studio shots of each vehicle class
 * (Kolkata's yellow Ambassador taxi, the toto and the green-and-yellow auto among them), 16:9 key art for every event
 * kind the deck can show, staged in Kolkata (Howrah Bridge, Vidyasagar Setu, the Victoria Memorial, a north Kolkata
 * lane, a Puja pandal, Eden Gardens, Howrah Station, Babughat), and wide Hooghly scenes for the Home greeting. Every file is
 * an original illustration, never a photo and never a sensor image; each is served from the deck's own origin (the
 * public pages' strict CSP allows it) and lazy-loaded with its size set.
 */

export const KEY_ART = { w: 640, h: 360 } as const;
export const VEHICLE_SHOT = { w: 480, h: 300 } as const;
export const SCENE = { w: 960, h: 320 } as const;

