/** The key-art kind for an event kind / OSINT class (the advisory scene when nothing fits). */
export function keyArtKind(kind: string | null | undefined): KeyArtKind {
	const k = (kind ?? '').toLowerCase().trim().replace(/[\s-]+/g, '_');
	if (KINDS.has(k)) return k as KeyArtKind;
	return KIND_ALIAS[k] ?? 'advisory';
}

/** The 16:9 key art for an event kind. */
export function keyArt(kind: string | null | undefined): string {
	return `/artwork/events/${keyArtKind(kind)}.svg`;
}

